            OpCode::SetProperty => Op::SetProperty {
                index: self.read_index()?,
            },
            OpCode::SetSlot => Op::SetSlot {
                index: self.read_u30()?,
            },
            OpCode::SetSuper => Op::SetSuper {
                index: self.read_index()?,
            },
            OpCode::Sf32 => Op::Sf32,
            OpCode::Sf64 => Op::Sf64,
            OpCode::Si16 => Op::Si16,
            OpCode::Si32 => Op::Si32,
            OpCode::Si8 => Op::Si8,
            OpCode::StrictEquals => Op::StrictEquals,
            OpCode::Subtract => Op::Subtract,
            OpCode::SubtractI => Op::SubtractI,
            OpCode::Swap => Op::Swap,
            OpCode::Sxi1 => Op::Sxi1,
